# Check for solutions to 5*b1^2 + 5*b2^2 + 8*b1*b2 = 63, where |b1|, |b2| <= 3.
# We only need to check b1 >= 0, b2 >= 0 and then account for symmetry/signs if necessary,
# but since the equation is symmetric in b1 and b2, iterating over a small range is fine.

solutions_found = False
for b1 in range(-3, 4):
    for b2 in range(-3, 4):
        LHS = 5*b1**2 + 5*b2**2 + 8*b1*b2
        if LHS == 63:
            print(f"Solution found: b1={b1}, b2={b2}")
            solutions_found = True
            break
    if solutions_found:
        break

if not solutions_found:
    print("No integer solutions found for b1, b2 in the range [-3, 3].")

